import fitz
doc = fitz.open('/root/latex_paper.pdf')
for i in range(doc.page_count):
    page = doc[i]
    # Get text blocks with positions
    blocks = page.get_text("dict")["blocks"]
    print(f"\n=== PAGE {i+1} ===")
